# Clothing builders shared by the cast (exec'd after base_body.py / littlechip.py helpers are loaded).
# Garments are generated by ray-casting from the body axis so hems are clean lines with tidy quad grids.
import math
import bpy
import bmesh
from mathutils import Vector, Quaternion


def plain_material(name, hexcol, rough=0.6, metal=0.0, vcol=False):
    m = material(name, hexcol, rough)
    b = next(n for n in m.node_tree.nodes if n.type == 'BSDF_PRINCIPLED')
    b.inputs['Metallic'].default_value = metal
    if vcol:
        nt = m.node_tree
        ca = next((n for n in nt.nodes if n.type == 'VERTEX_COLOR'), None) or nt.nodes.new('ShaderNodeVertexColor')
        ca.layer_name = 'Col'
        nt.links.new(ca.outputs['Color'], b.inputs['Base Color'])
    return m


def _sm01(x):
    x = max(0.0, min(1.0, x))
    return x * x * (3 - 2 * x)


def _solid(ob, t, offset=-1):
    so = ob.modifiers.new('Solid', 'SOLIDIFY')
    so.thickness = t
    so.offset = offset
    apply_modifiers(ob)


def _finish(name, bm):
    me = bpy.data.meshes.new(name)
    bm.to_mesh(me)
    bm.free()
    ob = _link(name, me)
    for p in me.polygons:
        p.use_smooth = True
    return ob


def body_radius(bvh, z, a, yc=0.006, maxr=0.2):
    """Distance from the torso axis to the body surface at height z, azimuth a (0 = front / -Y)."""
    d = Vector((math.sin(a), -math.cos(a), 0))
    hit, nrm, _, dist = bvh.ray_cast(Vector((0, yc, z)), d, maxr)
    return dist if hit is not None else maxr


def torso_garment(name, body, zbot, ztop, off, na=64, nz=14, yc=0.006, maxr=None):
    """Grid wrapped round the torso between zbot(a) and ztop(a), pushed out by off(a, z)."""
    _replace(name)
    bvh = _bvh(body)
    bm = bmesh.new()
    rows = []
    for j in range(nz + 1):
        row = []
        for i in range(na):
            a = 2 * math.pi * i / na
            z0, z1 = zbot(a), ztop(a)
            z = z0 + (z1 - z0) * j / nz
            r = body_radius(bvh, z, a, yc)
            if maxr:
                r = min(r, maxr(a, z))
            r += off(a, z)
            row.append(bm.verts.new((math.sin(a) * r, yc - math.cos(a) * r, z)))
        rows.append(row)
    for j in range(nz):
        for i in range(na):
            bm.faces.new((rows[j][i], rows[j][(i + 1) % na], rows[j + 1][(i + 1) % na], rows[j + 1][i]))
    top_ring = [v.co.copy() for v in rows[-1]]
    return _finish(name, bm), top_ring


def lace_strip(name, ring, depth=0.016, scallops=26, front_only=0.6):
    """Scalloped strip hanging from a ring of points (e.g. a neckline)."""
    _replace(name)
    n = len(ring)
    bm = bmesh.new()
    up, lo = [], []
    for i, p in enumerate(ring):
        a = 2 * math.pi * i / n
        outward = Vector((p.x, p.y - 0.006, 0)).normalized()
        sc = abs(math.sin(math.pi * scallops * i / n))
        front = max(0.0, math.cos(a))
        d = depth * (0.55 + 0.45 * sc) * ((1 - front_only) + front_only * front)
        up.append(bm.verts.new(p + outward * 0.004 + Vector((0, 0, 0.004))))
        lo.append(bm.verts.new(p + outward * 0.0075 - Vector((0, 0, d))))
    for i in range(n):
        bm.faces.new((lo[i], lo[(i + 1) % n], up[(i + 1) % n], up[i]))
    ob = _finish(name, bm)
    _solid(ob, 0.002)
    return ob


def bow(bm, c, size):
    """Ribbon bow facing -Y: two loops, knot, two tails."""
    c = Vector(c)
    S = lambda x, y, z: c + Vector((x, y, z)) * size
    for s in (1, -1):
        loft(bm, [(S(s * .12, 0, 0), .08 * size, .05 * size), (S(s * .55, -.05, .2), .22 * size, .08 * size),
                  (S(s * .95, 0, .02), .2 * size, .07 * size), (S(s * 1.0, 0, -.06), .02 * size, .02 * size)],
             ref=(0, 0, 1), seg=3, ring=8)
        loft(bm, [(S(s * .05, 0, -.1), .09 * size, .03 * size), (S(s * .25, -.03, -.6), .1 * size, .03 * size),
                  (S(s * .4, -.03, -1.0), .11 * size, .025 * size)], ref=(1, 0, 0), seg=3, ring=6)
    loft(bm, [(S(0, .03, 0), .14 * size, .1 * size), (S(0, -.08, 0), .15 * size, .12 * size), (S(0, -.1, 0), .05 * size, .05 * size)],
         ref=(1, 0, 0), seg=2, ring=8)


def chain_links(bm, path, link_r=0.0085, wire=0.0028):
    """Alternating oval links along a polyline (each link a thin torus)."""
    for k, (p0, p1) in enumerate(zip(path, path[1:])):
        mid = (p0 + p1) / 2
        d = (p1 - p0).normalized()
        res = bmesh.ops.create_circle(bm, cap_ends=True, radius=link_r, segments=8)
        ring = res['verts']
        bmesh.ops.scale(bm, vec=(1.7, 1.0, 1.0), verts=ring)            # oval along local X
        rot = Vector((1, 0, 0)).rotation_difference(d)
        if k % 2:
            rot = rot @ Quaternion((1, 0, 0), math.pi / 2)
        bmesh.ops.rotate(bm, cent=(0, 0, 0), matrix=rot.to_matrix(), verts=ring)
        bmesh.ops.translate(bm, vec=mid, verts=ring)


# ------------------------------------------------------------------ leg profile (matches base_body.build_body)
LEG = [((.08, .01, .835), .064), ((.083, .006, .74), .063), ((.085, .003, .64), .056), ((.087, 0, .55), .048),
       ((.088, 0, .48), .042), ((.089, .006, .41), .0445), ((.09, .01, .33), .044), ((.09, .012, .24), .0345),
       ((.091, .012, .15), .0275), ((.091, .012, .09), .0245), ((.091, .012, .05), .0245)]


def leg_at(z):
    for (p0, r0), (p1, r1) in zip(LEG, LEG[1:]):
        if p1[2] <= z <= p0[2]:
            t = (p0[2] - z) / (p0[2] - p1[2])
            return Vector(p0).lerp(Vector(p1), t), (r0 + (r1 - r0) * t) * LEG_K[BODY_KIND]
    k = LEG_K[BODY_KIND]
    return (Vector(LEG[0][0]), LEG[0][1] * k) if z > LEG[0][0][2] else (Vector(LEG[-1][0]), LEG[-1][1] * k)
